from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression
from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.SwActivationFactory import SwActivationFactory
from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


scorpio_sws = ["urm6", "erm6"]
amber_master_sws = ["trm6", "srm6", "lrm6"]
chile_sws = ["chb0"]
gen4_5g = ["5gh4, 5ga4", "5ge4"]
pulsar = ["5gb4"]


class SwUpdate(OperationPrototype):
    def __init__(self, bts):
        super(SwUpdate, self).__init__(bts)
        self.operation_details = {
            "Timeout": 0,
            "Operation": "Complete bts software update",
            "Start point": "SW download begins",
            "End point": "First cell up",
            "Requirement": "OM_GEN_SFS_PERF_CAP.13391",
        }

    def get_kpi(self, inter_release=False):
        """
        Gets kpi for software update operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software update
        :rtype: dict
        """
        log_suppression("There was no configuration found in Gates tool for Your setup, "
                        "returning default timeout for software activation. Please, do not base Your pronto "
                        "on that value.")

        self.operation_details["Timeout"] += 1000
        self._get_sw_activation_kpi_and_include_preperation_gap(inter_release=inter_release)
        return self.operation_details

    def _get_sw_activation_kpi_and_include_preperation_gap(self, inter_release):
        preperation_gap = 120
        self.operation_details["Timeout"] += preperation_gap
        sw_activation_operation = SwActivationFactory()
        sw_activation_operation.bts_setter(self.bts)
        self.sw_activation_operation_details = sw_activation_operation.get_kpi(inter_release=inter_release)
        self.operation_details["Timeout"] += self.sw_activation_operation_details["Timeout"]
        self.operation_details["Requirement"] += " + " + self.sw_activation_operation_details["Requirement"]
